/**
 * The behaviour snapshots (Task S8) are regenerated by `npm run snapshots` and diffed by
 * `npm run upgrade:check`, so two runs on the same inputs must give byte-identical files.
 */
import { describe, expect, it } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import { buildDataSnapshot } from '../../scripts/deps/dataSnapshot';
import { formatHarperSnapshot, snapshotDocuments, type SnapshotInput } from '../../scripts/deps/harperSnapshot';
import { buildLicenceSnapshot, type CargoMetadata } from '../../scripts/deps/licenceSnapshot';
import { readNpmLicences } from '../../scripts/deps/licences';
import { createLinter } from '@/engine/linter';

const ROOT = path.resolve(__dirname, '../..');
const formatJson = (value: unknown) => JSON.stringify(value, null, 2);

describe('snapshot scripts are deterministic', () => {
  it('data snapshot: dictionary counts and lookups, word-list counts and hashes', async () => {
    const first = formatJson(await buildDataSnapshot(ROOT));
    const second = formatJson(await buildDataSnapshot(ROOT));
    expect(second).toBe(first);
    const snapshot = JSON.parse(first);
    expect(Object.keys(snapshot.dictionary.lookups)).toHaveLength(50);
    expect(snapshot.wordlists['en-IN'].count).toBeGreaterThan(600);
  });

  it('Harper snapshot: two runs with fresh linters give the same flags', async () => {
    const inputs: SnapshotInput[] = ['academic/groundwater-marathwada.md', 'blog/freelancer-taxes.docx'].map((file) => ({
      id: `reference/${file}`,
      fileName: file,
      bytes: new Uint8Array(fs.readFileSync(path.join(ROOT, 'trust/reference', file))),
      source: 'trust/reference',
      licence: 'Apache-2.0',
      storeText: true,
    }));
    const run = async () => formatHarperSnapshot({ harper: 'test', reference: await snapshotDocuments(await createLinter('American'), inputs), samples: [], probes: [] });
    const first = await run();
    expect(await run()).toBe(first);
    expect(first).toContain('"kind":"Spelling"');
  }, 60_000);

  it('Harper snapshot: a hash-only source keeps offsets and kinds but no text', async () => {
    const input: SnapshotInput = {
      id: 'samples/example.txt',
      fileName: 'example.txt',
      bytes: new TextEncoder().encode('Teh results was clear.'),
      source: 'https://example.org',
      licence: 'CC-BY-4.0',
      storeText: false,
    };
    const [doc] = await snapshotDocuments(await createLinter('American'), [input]);
    expect(doc.flags.length).toBeGreaterThan(0);
    for (const flag of doc.flags) {
      expect(Object.keys(flag)).toEqual(['kind', 'para', 'start', 'end', 'hash']);
    }
  });

  it('licence snapshot: the same packages in any order give the same file', () => {
    const npm = readNpmLicences(path.join(ROOT, 'tests/fixtures/licences')).packages;
    const metadata: CargoMetadata = {
      workspace_members: ['path+file:///app#writing-check@0.1.0'],
      packages: [
        { id: 'registry+https://github.com/rust-lang/crates.io-index#serde@1.0.0', name: 'serde', version: '1.0.0', license: 'MIT OR Apache-2.0' },
        { id: 'path+file:///app#writing-check@0.1.0', name: 'writing-check', version: '0.1.0', license: null },
        { id: 'registry+https://github.com/rust-lang/crates.io-index#anyhow@1.0.0', name: 'anyhow', version: '1.0.0', license: 'MIT OR Apache-2.0' },
      ],
    };
    const reversed: CargoMetadata = { ...metadata, packages: [...metadata.packages].reverse() };
    const first = formatJson(buildLicenceSnapshot(npm, metadata));
    expect(formatJson(buildLicenceSnapshot([...npm].reverse(), reversed))).toBe(first);
    expect(JSON.parse(first)).toEqual({
      npm: {
        '@fake-scope/object-licence@3.0.0': 'BSD-3-Clause',
        'fake-dev-optional@1.0.0': 'Apache-2.0',
        'fake-mit@1.0.0': 'MIT',
        'fake-nc@1.0.0': 'CC-BY-NC-4.0',
        'fake-nested@2.0.0': 'ISC',
      },
      crates: { 'anyhow@1.0.0': 'MIT OR Apache-2.0', 'serde@1.0.0': 'MIT OR Apache-2.0' },
    });
  });
});
